using System;
using System.IO;
using Newtonsoft.Json.Linq;

public class CPHInline
{
    public bool Execute()
    {
        string userId = args["userId"].ToString();
        string userName = args["userName"].ToString();
        string inputText = args["rawInput"].ToString();

        // Parse amount
        if (string.IsNullOrEmpty(inputText)) {
            CPH.SendMessage($"@{userName}, usage: !buyRRT [amount]. Example: !buyRRT 10");
            return false;
        }

        int amount;
        if (!int.TryParse(inputText, out amount) || amount < 1) {
            CPH.SendMessage($"@{userName}, please specify a valid amount (minimum 1).");
            return false;
        }

        int cost = amount * 50;

        // Load user data
        string dataPath = @"C:\StreamerBot\UserData\eggs.json";
        string jsonData = File.ReadAllText(dataPath);
        JObject data = JObject.Parse(jsonData);

        // Initialize user if needed
        if (data["users"] == null) data["users"] = new JObject();
        if (data["users"][userId] == null) {
            data["users"][userId] = new JObject();
            data["users"][userId]["eggs"] = 0;
            data["users"][userId]["d20Tokens"] = 0;
            data["users"][userId]["rrTokens"] = 0;
        }

        int currentEggs = (int)(data["users"][userId]["eggs"] ?? 0);

        if (currentEggs < cost) {
            CPH.SendMessage($"@{userName}, you don't have enough eggs! You have {currentEggs} eggs, but need {cost} eggs.");
            return false;
        }

        // Process purchase
        data["users"][userId]["eggs"] = currentEggs - cost;
        data["users"][userId]["rrTokens"] = (int)(data["users"][userId]["rrTokens"] ?? 0) + amount;

        File.WriteAllText(dataPath, data.ToString());

        CPH.SendMessage($"🎰 @{userName} purchased {amount} RRToken(s) for {cost} eggs! Remaining: {currentEggs - cost} eggs.");
        return true;
    }
}
